/* jQuery (simplified example — put the real one here) */
window.jQuery = window.$ = function (selector) {
    const el = typeof selector === 'string' ? document.querySelector(selector) : selector;
    return {
        text: (t) => { if (t === undefined) return el.textContent; el.textContent = t; return this; },
        addClass: (c) => { el.classList.add(c); return this; },
        removeClass: (c) => { el.classList.remove(c); return this; },
        on: (e, fn) => { el.addEventListener(e, fn); return this; }
    };
};